def _write_jsonl(lines: list[str], suffix: str = ".jsonl") -> Path:
    """Helper to write JSONL lines to a temp file and return the path."""
    f = tempfile.NamedTemporaryFile(mode="w", suffix=suffix, delete=False, encoding="utf-8")
    for line in lines:
        f.write(line + "\n")
    f.close()
    return Path(f.name)

